BEGIN;
INSERT INTO notas (id, titulo, dominio_slug, aplicacao_slug, tipo_nota_slug, camadas, sinais, confianca, status, corpo) VALUES (
  $m1776$nota-0164$m1776$, $m1777$VO2máx alto não garante melhor desempenho: atleta com VO2máx menor mas maior economia/FTP pode superar atleta com VO2máx maior — desempenho depende da interação entre VO2máx, limiares, economia, capacidade anaeróbia, durabilidade e estratégia$m1777$, $m1778$contexto-atleta$m1778$,
  $m1779$contexto$m1779$, $m1780$conceito$m1780$,
  ARRAY[$m1781$mensal$m1781$]::text[], '{}'::text[],
  0.55, $m1782$ativo$m1782$, $m1783$Exemplo didático do Manual: Atleta A tem VO2máx de 82 mL·kg⁻¹·min⁻¹ mas FTP de apenas 300W (baixa economia); Atleta B tem VO2máx menor (74) mas FTP maior (340W) e maior resistência à fadiga — o Manual conclui que o Atleta B provavelmente venceria uma prova de estrada. O desempenho depende da interação entre VO2máx, limiares fisiológicos, economia de movimento, capacidade anaeróbia, durabilidade, estratégia e fatores psicológicos — nenhum fator isolado prevê o resultado.

Aplicação ao feedback: reforça um princípio já presente implicitamente no cânone (Livro 1 prioriza FTP/potência-por-peso como métricas práticas derivadas do Strava, em vez de VO2máx laboratorial) — o produto deve evitar qualquer comparação ou ranking de atletas baseado unicamente em capacidade aeróbia máxima; a FTP e a curva de potência-duração (já cobertas pelo Livro 1) são proxies mais completas e diretamente derivadas de dados do Strava.$m1783$
)
